// Sprint 17 — VWAP/TWAP Execution Engine & Almgren-Chriss Optimal Liquidation
// All types for execution algorithm studio

export type ExecutionAlgoType = 'VWAP' | 'TWAP' | 'ALMGREN_CHRISS' | 'ICEBERG_PEGGED';

export type OrderSide = 'BUY' | 'SELL';

/** A single child order slice generated by an execution algorithm */
export interface ChildOrderSlice {
  sliceIndex: number;
  /** Minutes from order start */
  scheduledTime: number;
  /** Target quantity for this slice */
  targetQty: number;
  /** Actually executed quantity (simulated) */
  executedQty: number;
  /** Arrival/decision price at slice time */
  benchmarkPrice: number;
  /** Simulated fill price (benchmark ± market impact + noise) */
  fillPrice: number;
  /** Slippage in basis points vs benchmark */
  slippageBps: number;
  /** Cumulative executed quantity after this slice */
  cumulativeQty: number;
  /** Volume-weighted avg price up to this slice */
  runningVwap: number;
}

/** Indian NSE intraday volume profile bucket */
export interface VolumeProfilePoint {
  /** Minutes from open (9:15 AM = 0) */
  timeMinutesFromOpen: number;
  /** HH:MM label for display */
  timeLabel: string;
  /** Fraction of daily volume in this bucket (sum = 1.0) */
  volumeFraction: number;
  /** Human-readable description of the market phase */
  description: string;
}

/** Almgren-Chriss optimal liquidation model parameters */
export interface AlmgrenChrissParams {
  /** Total shares/contracts to liquidate */
  totalQty: number;
  /** Execution horizon in minutes */
  horizonMinutes: number;
  /** Risk-aversion coefficient λ (higher = more front-loaded) */
  riskAversion: number;
  /** Daily volatility of the asset (annualized σ / sqrt(252)) */
  sigma: number;
  /** Permanent market impact coefficient η (₹ per share per unit traded) */
  permanentImpact: number;
  /** Temporary market impact coefficient γ (₹ per share per unit per minute) */
  temporaryImpact: number;
  /** Arrival (decision) price in ₹ */
  arrivalPrice: number;
}

/** Perold Implementation Shortfall decomposition */
export interface ImplementationShortfallBreakdown {
  /** Total IS in basis points vs arrival price */
  totalBps: number;
  /** Delay cost (time between decision and first execution) */
  delayBps: number;
  /** Temporary market impact cost */
  temporaryImpactBps: number;
  /** Permanent market impact (adverse price drift) */
  permanentImpactBps: number;
  /** Statutory fee drag (STT + stamp + SEBI + brokerage) */
  statutoryFeeDragBps: number;
  /** Opportunity cost from unfilled slices */
  opportunityCostBps: number;
}

/** Full execution summary for a parent order */
export interface ExecutionSummary {
  parentOrderId: string;
  ticker: string;
  side: OrderSide;
  algo: ExecutionAlgoType;
  /** All child slices */
  slices: ChildOrderSlice[];
  /** Volume-weighted avg fill price across all slices */
  avgExecutedPrice: number;
  /** Arrival (decision) price when parent was placed */
  arrivalPrice: number;
  /** Market VWAP over the execution window */
  marketVwap: number;
  /** Implementation shortfall vs arrival price (bps) */
  implementationShortfallBps: number;
  /** IS vs market VWAP (bps) */
  vsMarketVwapBps: number;
  /** IS decomposition */
  isBreakdown: ImplementationShortfallBreakdown;
  /** Total statutory charges in ₹ */
  totalStatutoryCharges: number;
  /** Total executed notional in ₹ */
  executedNotional: number;
  /** Almgren-Chriss params (only present when algo === ALMGREN_CHRISS) */
  almgrenChrissParams?: AlmgrenChrissParams;
  /** Execution start time (ISO string) */
  startTime: string;
  /** Execution end time (ISO string) */
  endTime: string;
}

/** Comparison of two algorithms on the same order */
export interface AlgoComparison {
  vwap?: ExecutionSummary;
  twap?: ExecutionSummary;
  almgrenChriss?: ExecutionSummary;
}
